-- #987 wave 1 (pure additions): Dread Wastes creature abilities, imported from DeltaTho PR 15 file 2026_10_25_37_world.sql.
-- 68 creatures, 172 smart_scripts rows. Only creatures that have NO source_type 0 rows today are written here;
-- scripts that would replace existing rows are wave 2. Filters/fixes: see (not shipped)
-- Idempotent: DELETE of the listed entries then INSERT. AIName is set to SmartAI only where AIName and ScriptName are empty.
-- Undo: DELETE FROM smart_scripts WHERE source_type=0 AND FIND_IN_SET(entryorguid, <entries below>); and
--   UPDATE creature_template SET AIName='' WHERE FIND_IN_SET(entry, <entries below>); (entries that already had AIName SmartAI: see backup in (not shipped).

SET @ENTRIES := '6250,62000,62023,62228,62582,62680,62755,62763,62813,62814,62832,62833,62843,62863,63007,63102,63103,63104,63206,63257,63294,63339,63347,63348,63368,63369,63375,63465,63466,63470,63729,63827,63833,63865,63944,63999,64008,64273,64485,64641,64714,64831,64970,64973,65118,65231,65251,65273,65274,65312,65330,65551,65575,65646,65685,65995,66188,66194,66319,66549,66587,66595,66599,66783,66789,66868,66880,67160';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `AIName` = '' AND `ScriptName` = '' AND FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
